type SiteDraft = Omit<Territory, 'x' | 'y'> & { px: number; py: number; siteType: StrategicSiteType; theater: TheaterId };
const expandedPoints: Record<TheaterId, Record<string, { x: number; y: number }>> = { europe: {}, asia: {} };

function site({ px, py, ...draft }: SiteDraft): Territory {
  expandedPoints[draft.theater][draft.id] = { x: px, y: py };
  return { ...draft, x: px / 12, y: py / 7.6 };
}

