export const expandedHistoricalMapPoints = expandedPoints;

export function buildStrategicTerritories(base: Territory[]): Territory[] {
  const combined = [
    ...base.map((territory) => ({ ...territory, ...(baseEnhancements[territory.id] ?? {}) })),
    ...expandedTerritories,
  ];
  const byId = new Map(combined.map((territory) => [territory.id, territory]));
  const neighborSets = new Map(combined.map((territory) => [territory.id, new Set(territory.neighbors)]));

  combined.forEach((territory) => {
    territory.neighbors.forEach((neighborId) => {
      if (!byId.has(neighborId)) return;
      neighborSets.get(neighborId)?.add(territory.id);
    });
  });

  return combined.map((territory) => ({
    ...territory,
    neighbors: [...(neighborSets.get(territory.id) ?? [])].filter((id) => byId.has(id)).sort(),
  }));
}
